module.exports = "<!doctype html>\r\n<html lang=\"pt-BR\">\r\n<head>\r\n<meta charset=\"utf-8\">\r\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\r\n<meta name=\"theme-color\" content=\"#0e1015\">\r\n<title>Nintendo 64 (N64) — Jogos 3D em Português — Continue?</title>\r\n<link rel=\"icon\" type=\"image/x-icon\" href=\"favicon.ico\">\r\n<link rel=\"icon\" type=\"image/png\" sizes=\"32x32\" href=\"favicon-32.png\">\r\n<link rel=\"icon\" type=\"image/png\" sizes=\"16x16\" href=\"favicon-16.png\">\r\n<link rel=\"apple-touch-icon\" sizes=\"180x180\" href=\"apple-touch-icon.png\">\r\n<style>\r\n@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@400;500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700&family=Space+Grotesk:wght@600;700;800&display=swap');\r\n\r\n:root {\r\n  --bg: #0c0f17;\r\n  --bg-soft: #121722;\r\n  --panel: #161c2b;\r\n  --panel-elevated: #1e2638;\r\n  --panel-hover: #263148;\r\n  --line: #242e42;\r\n  --line-bright: #364462;\r\n  --ink: #F5F7FA;\r\n  --muted: #9AA5B8;\r\n  --dim: #64748B;\r\n\r\n  --red: #FF3B30;\r\n  --red-hover: #FF5247;\r\n  --red-soft: rgba(255, 59, 48, 0.14);\r\n  --red-border: rgba(255, 59, 48, 0.38);\r\n\r\n  --n64-blue: #00E5FF;\r\n  --n64-blue-hover: #33ECFF;\r\n  --n64-blue-soft: rgba(0, 229, 255, 0.14);\r\n  --n64-blue-border: rgba(0, 229, 255, 0.4);\r\n\r\n  --n64-yellow: #FFD700;\r\n  --n64-yellow-soft: rgba(255, 215, 0, 0.16);\r\n\r\n  --n64-green: #10B981;\r\n  --n64-green-soft: rgba(16, 185, 129, 0.15);\r\n\r\n  --mono: 'JetBrains Mono', monospace;\r\n  --sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\r\n  --display: 'Space Grotesk', sans-serif;\r\n  --radius-lg: 14px;\r\n  --radius-md: 12px;\r\n  --radius-sm: 8px;\r\n}\r\n\r\n* {\r\n  box-sizing: border-box;\r\n}\r\n\r\nhtml {\r\n  scroll-behavior: smooth;\r\n  overflow-x: hidden;\r\n}\r\n\r\nbody {\r\n  margin: 0;\r\n  background-color: var(--bg);\r\n  color: var(--ink);\r\n  font-family: var(--sans);\r\n  min-height: 100vh;\r\n  overflow-x: hidden;\r\n  -webkit-font-smoothing: antialiased;\r\n}\r\n\r\nbutton, input, a {\r\n  font: inherit;\r\n  color: inherit;\r\n}\r\n\r\nbutton {\r\n  cursor: pointer;\r\n}\r\n\r\n.shell {\r\n  max-width: 1380px;\r\n  margin: 0 auto;\r\n  padding: 0 36px;\r\n}\r\n\r\n/* STICKY TOPBAR */\r\n.topbar-wrap {\r\n  position: sticky;\r\n  top: 0;\r\n  z-index: 60;\r\n  background: rgba(12, 15, 23, 0.94);\r\n  backdrop-filter: blur(12px);\r\n  -webkit-backdrop-filter: blur(12px);\r\n  border-bottom: 1px solid var(--line);\r\n}\r\n\r\n.topbar {\r\n  max-width: 1380px;\r\n  margin: 0 auto;\r\n  padding: 0 24px;\r\n  min-height: 64px;\r\n  height: auto;\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 16px;\r\n  flex-wrap: nowrap;\r\n}\r\n\r\n.brand {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  text-decoration: none;\r\n  font-family: var(--display);\r\n  font-weight: 700;\r\n  font-size: 21px;\r\n  letter-spacing: -0.6px;\r\n  flex-shrink: 0;\r\n  color: #FFFFFF;\r\n  order: 1;\r\n}\r\n\r\n.brand-logo-img {\r\n  height: 44px;\r\n  width: auto;\r\n  max-width: 140px;\r\n  object-fit: contain;\r\n  display: block;\r\n  border-radius: 6px;\r\n  box-shadow: 0 0 14px rgba(230, 0, 18, 0.35);\r\n  border: 1px solid rgba(255, 255, 255, 0.12);\r\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\r\n}\r\n\r\n.brand:hover .brand-logo-img {\r\n  transform: scale(1.05);\r\n  box-shadow: 0 0 22px rgba(230, 0, 18, 0.65);\r\n}\r\n\r\n.brand-mark {\r\n  width: 34px;\r\n  height: 34px;\r\n  background: linear-gradient(135deg, #00E5FF, #0077FF);\r\n  color: #FFFFFF;\r\n  display: grid;\r\n  place-items: center;\r\n  border-radius: 8px;\r\n  font-size: 15px;\r\n  font-weight: 800;\r\n  transition: transform 0.18s ease, box-shadow 0.18s ease;\r\n  box-shadow: 0 0 12px rgba(0, 229, 255, 0.35);\r\n}\r\n\r\n.brand:hover .brand-mark {\r\n  transform: translateY(-1px) rotate(4deg);\r\n  box-shadow: 0 0 18px rgba(0, 229, 255, 0.55);\r\n}\r\n\r\n.brand-q {\r\n  color: var(--n64-blue);\r\n}\r\n\r\n.brand-sub {\r\n  font: 700 10px var(--mono);\r\n  color: var(--n64-yellow);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n  padding-left: 12px;\r\n  border-left: 1px solid var(--line-bright);\r\n}\r\n\r\n.nav {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  overflow-x: auto;\r\n  overflow-y: hidden;\r\n  white-space: nowrap;\r\n  -webkit-overflow-scrolling: touch;\r\n  scroll-behavior: smooth;\r\n  scrollbar-width: thin;\r\n  scrollbar-color: rgba(255, 215, 0, 0.45) rgba(255, 255, 255, 0.05);\r\n  flex: 1;\r\n  min-width: 0;\r\n  padding: 8px 12px 10px 4px;\r\n  order: 2;\r\n  font: 600 12px var(--sans);\r\n}\r\n\r\n.nav::-webkit-scrollbar {\r\n  height: 5px;\r\n  display: block;\r\n}\r\n\r\n.nav::-webkit-scrollbar-track {\r\n  background: rgba(255, 255, 255, 0.06);\r\n  border-radius: 999px;\r\n  margin: 0 4px;\r\n}\r\n\r\n.nav::-webkit-scrollbar-thumb {\r\n  background: linear-gradient(90deg, #ffd700, #00e5ff);\r\n  border-radius: 999px;\r\n  box-shadow: 0 0 8px rgba(255, 215, 0, 0.5);\r\n}\r\n\r\n.nav::-webkit-scrollbar-thumb:hover {\r\n  background: linear-gradient(90deg, #10b981, #ffd700);\r\n}\r\n\r\n.nav-link {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid transparent;\r\n  color: var(--muted);\r\n  text-decoration: none;\r\n  transition: all 0.16s ease;\r\n  white-space: nowrap;\r\n  background: transparent;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.nav-link:hover {\r\n  color: #FFFFFF;\r\n  background: var(--panel);\r\n  border-color: var(--line);\r\n}\r\n\r\n.nav-link.active {\r\n  color: #0c0f17;\r\n  background: #FFFFFF;\r\n  border-color: #FFFFFF;\r\n  font-weight: 700;\r\n}\r\n\r\n.nav-badge {\r\n  font: 600 10px var(--mono);\r\n  padding: 2px 7px;\r\n  border-radius: 6px;\r\n  background: var(--panel-elevated);\r\n  color: var(--ink);\r\n  border: 1px solid var(--line-bright);\r\n}\r\n\r\n.nav-link.active .nav-badge {\r\n  background: #0c0f17;\r\n  color: #FFFFFF;\r\n  border-color: #0c0f17;\r\n}\r\n\r\n.nav-badge.blue {\r\n  background: var(--n64-blue-soft);\r\n  color: var(--n64-blue);\r\n  border-color: var(--n64-blue-border);\r\n}\r\n\r\n.nav-badge.gold {\r\n  background: var(--n64-yellow-soft);\r\n  color: var(--n64-yellow);\r\n  border-color: rgba(255, 215, 0, 0.4);\r\n}\r\n\r\n.nav-badge.red {\r\n  background: var(--red-soft);\r\n  color: #FF5247;\r\n  border-color: var(--red-border);\r\n}\r\n\r\n.top-right-actions {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-shrink: 0;\r\n  order: 3;\r\n  padding-left: 14px;\r\n  border-left: 1px solid rgba(255, 255, 255, 0.08);\r\n  position: relative;\r\n  z-index: 5;\r\n}\r\n  gap: 8px;\r\n  flex-shrink: 0;\r\n  order: 3;\r\n}\r\n\r\n.btn-top-mapper {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 7px;\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  color: #FFFFFF;\r\n  font: 700 12px var(--sans);\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  cursor: pointer;\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.btn-top-mapper:hover {\r\n  border-color: var(--n64-blue);\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.pad-dot {\r\n  width: 8px;\r\n  height: 8px;\r\n  border-radius: 50%;\r\n  background: var(--n64-green);\r\n  display: inline-block;\r\n  box-shadow: 0 0 8px var(--n64-green);\r\n}\r\n\r\n/* HERO SECTION */\r\n.hero {\r\n  padding: 38px 0 26px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-end;\r\n  gap: 28px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.eyebrow {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font: 700 11px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n  color: #FFFFFF;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-left: 3px solid var(--n64-blue);\r\n  padding: 6px 12px;\r\n  border-radius: 6px;\r\n}\r\n\r\n.hero h1 {\r\n  font-family: var(--display);\r\n  font-size: clamp(34px, 4.8vw, 60px);\r\n  letter-spacing: -2px;\r\n  line-height: 1.02;\r\n  margin: 14px 0 12px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.hero h1 span {\r\n  background: linear-gradient(135deg, #00E5FF, #FFD700);\r\n  -webkit-background-clip: text;\r\n  -webkit-text-fill-color: transparent;\r\n  filter: drop-shadow(0 0 16px rgba(0, 229, 255, 0.35));\r\n}\r\n\r\n.intro {\r\n  max-width: 680px;\r\n  color: var(--muted);\r\n  line-height: 1.62;\r\n  font-size: 15.5px;\r\n  margin: 0;\r\n}\r\n\r\n.intro b {\r\n  color: #FFFFFF;\r\n}\r\n\r\n.hero-actions {\r\n  display: flex;\r\n  gap: 10px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.btn-mapper-hero {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  min-height: 48px;\r\n  padding: 13px 20px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--n64-blue);\r\n  background: linear-gradient(135deg, #00C4DF, #0077FF);\r\n  color: #FFFFFF;\r\n  font: 700 13px var(--sans);\r\n  transition: transform 0.16s ease, box-shadow 0.16s ease;\r\n  box-shadow: 0 4px 14px rgba(0, 229, 255, 0.28);\r\n}\r\n\r\n.btn-mapper-hero:hover {\r\n  transform: translateY(-2px);\r\n  box-shadow: 0 6px 20px rgba(0, 229, 255, 0.45);\r\n}\r\n\r\n.btn-mapper-hero.yellow {\r\n  border-color: #FFD700;\r\n  background: linear-gradient(135deg, #F59E0B, #B45309);\r\n  box-shadow: 0 4px 14px rgba(245, 158, 11, 0.35);\r\n}\r\n\r\n.btn-mapper-hero.yellow:hover {\r\n  background: linear-gradient(135deg, #FBBF24, #D97706);\r\n}\r\n\r\n/* SECTION JUMP BAR */\r\n.section-nav {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: space-between;\r\n  gap: 12px;\r\n  flex-wrap: wrap;\r\n  padding: 12px 16px;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line);\r\n  border-radius: var(--radius-md);\r\n  margin-bottom: 26px;\r\n}\r\n\r\n.jump-links {\r\n  display: flex;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.jump-pill {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  padding: 9px 13px;\r\n  border-radius: var(--radius-sm);\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  text-decoration: none;\r\n  font: 600 12.5px var(--sans);\r\n  color: var(--ink);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.jump-pill span {\r\n  font: 700 10px var(--mono);\r\n  color: #0c0f17;\r\n  background: var(--n64-blue);\r\n  padding: 2px 6px;\r\n  border-radius: 4px;\r\n}\r\n\r\n.jump-pill:hover {\r\n  border-color: var(--n64-blue);\r\n  background: var(--panel-hover);\r\n  color: #FFFFFF;\r\n}\r\n\r\n/* BANNER DE BUSCA NO TOPO */\r\n.top-search-banner {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-md);\r\n  padding: 16px 20px;\r\n  margin: 18px 0 28px;\r\n  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.45);\r\n}\r\n\r\n.top-search-box {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 12px;\r\n  background: #080a10;\r\n  border: 1.5px solid var(--line-bright);\r\n  border-radius: var(--radius-sm);\r\n  padding: 0 16px;\r\n  height: 52px;\r\n  transition: border-color 0.2s, box-shadow 0.2s;\r\n}\r\n\r\n.top-search-box:focus-within {\r\n  border-color: var(--n64-blue);\r\n  box-shadow: 0 0 0 3px rgba(0, 229, 255, 0.2);\r\n}\r\n\r\n.top-search-box svg {\r\n  color: var(--n64-blue);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.top-search-box input {\r\n  flex: 1;\r\n  background: transparent;\r\n  border: 0;\r\n  outline: 0;\r\n  color: #FFFFFF;\r\n  font-size: 15px;\r\n  font-weight: 600;\r\n}\r\n\r\n.top-search-box input::placeholder {\r\n  color: #7B8B9E;\r\n  font-weight: 400;\r\n}\r\n\r\n.top-clear-btn {\r\n  background: var(--panel-elevated);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: 6px;\r\n  color: #FFFFFF;\r\n  font: 700 11px var(--sans);\r\n  padding: 6px 12px;\r\n  cursor: pointer;\r\n  display: none;\r\n}\r\n\r\n.top-clear-btn.visible {\r\n  display: inline-block;\r\n}\r\n\r\n.top-clear-btn:hover {\r\n  background: var(--red);\r\n  border-color: var(--red);\r\n}\r\n\r\n.top-search-hints {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 8px;\r\n  flex-wrap: wrap;\r\n  margin-top: 12px;\r\n  font-size: 12.5px;\r\n  color: var(--muted);\r\n}\r\n\r\n.search-tag {\r\n  background: var(--bg-soft);\r\n  border: 1px solid var(--line-bright);\r\n  color: #EEEEEE;\r\n  padding: 5px 12px;\r\n  border-radius: 20px;\r\n  font: 600 12px var(--sans);\r\n  cursor: pointer;\r\n  transition: all 0.15s;\r\n}\r\n\r\n.search-tag:hover {\r\n  background: var(--n64-blue);\r\n  color: #0c0f17;\r\n  border-color: var(--n64-blue);\r\n  font-weight: 700;\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* THEATER MODE N64 PLAYER DOCK */\r\n.player-dock {\r\n  display: none;\r\n  margin: 0 0 36px;\r\n  border: 2px solid var(--line-bright);\r\n  border-top: 4px solid var(--n64-blue);\r\n  border-radius: var(--radius-lg);\r\n  background: #080A10;\r\n  overflow: hidden;\r\n  box-shadow: 0 24px 64px rgba(0, 0, 0, 0.85);\r\n}\r\n\r\n.player-dock.open {\r\n  display: block;\r\n}\r\n\r\n.player-head {\r\n  padding: 14px 18px;\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  gap: 14px;\r\n  flex-wrap: wrap;\r\n  background: var(--panel);\r\n  border-bottom: 1px solid var(--line);\r\n}\r\n\r\n.player-now {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 14px;\r\n  min-width: 0;\r\n}\r\n\r\n.player-thumb {\r\n  width: 52px;\r\n  height: 52px;\r\n  border-radius: 6px;\r\n  object-fit: cover;\r\n  border: 1px solid var(--line-bright);\r\n  background: #0C0C0C;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.player-kicker {\r\n  font: 700 10px var(--mono);\r\n  color: var(--n64-blue);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.2px;\r\n}\r\n\r\n.player-title {\r\n  font-family: var(--display);\r\n  font-size: 18px;\r\n  font-weight: 700;\r\n  letter-spacing: -0.4px;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.player-controls-bar {\r\n  display: flex;\r\n  gap: 8px;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.dock-btn {\r\n  display: inline-flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  min-height: 40px;\r\n  padding: 8px 14px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--line-bright);\r\n  background: var(--panel-elevated);\r\n  color: #FFFFFF;\r\n  font: 700 12px var(--sans);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.dock-btn:hover {\r\n  border-color: #FFFFFF;\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.dock-btn.active {\r\n  border-color: var(--n64-yellow);\r\n  color: var(--n64-yellow);\r\n  background: var(--n64-yellow-soft);\r\n}\r\n\r\n.dock-btn.danger {\r\n  background: rgba(255, 59, 48, 0.16);\r\n  border-color: var(--red-border);\r\n}\r\n\r\n.dock-btn.danger:hover {\r\n  border-color: var(--red);\r\n  background: var(--red);\r\n  color: #FFFFFF;\r\n}\r\n\r\n.control-note {\r\n  padding: 12px 18px;\r\n  background: var(--bg-soft);\r\n  color: var(--muted);\r\n  border-bottom: 1px solid var(--line);\r\n  font: 600 12px var(--sans);\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n  gap: 10px;\r\n}\r\n\r\n.control-note b {\r\n  color: #FFFFFF;\r\n}\r\n\r\n#game-frame {\r\n  height: min(76vh, 740px);\r\n  min-height: 400px;\r\n  width: 100%;\r\n  border: 0;\r\n  display: block;\r\n  background: #06080C;\r\n}\r\n\r\n/* SECTIONS */\r\n.lib-section {\r\n  padding: 32px 0 38px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.section-header {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: flex-end;\r\n  gap: 16px;\r\n  margin-bottom: 22px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.section-index {\r\n  font: 700 11px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 1.4px;\r\n  color: var(--n64-blue);\r\n  margin-bottom: 6px;\r\n}\r\n\r\n.section-header h2 {\r\n  font-family: var(--display);\r\n  font-size: clamp(22px, 2.8vw, 30px);\r\n  letter-spacing: -0.8px;\r\n  margin: 0;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.section-sub {\r\n  font-size: 14px;\r\n  color: var(--muted);\r\n  margin: 5px 0 0;\r\n}\r\n\r\n/* N64 SHOWCASE (SEÇÃO A) */\r\n.n64-showcase {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 20px;\r\n}\r\n\r\n@media (max-width: 900px) {\r\n  .n64-showcase {\r\n    grid-template-columns: 1fr;\r\n  }\r\n}\r\n\r\n.n64-card {\r\n  display: grid;\r\n  grid-template-columns: 240px 1fr;\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-lg);\r\n  overflow: hidden;\r\n  transition: transform 0.2s cubic-bezier(0.2, 0.9, 0.4, 1), border-color 0.2s ease, box-shadow 0.2s ease;\r\n  position: relative;\r\n}\r\n\r\n@media (max-width: 580px) {\r\n  .n64-card {\r\n    grid-template-columns: 1fr;\r\n  }\r\n}\r\n\r\n.n64-card:hover {\r\n  transform: translateY(-3px);\r\n  border-color: var(--n64-blue);\r\n  box-shadow: 0 12px 32px rgba(0, 229, 255, 0.15);\r\n}\r\n\r\n.n64-art {\r\n  position: relative;\r\n  background: #080A10;\r\n  display: grid;\r\n  place-items: center;\r\n  border-right: 1px solid var(--line);\r\n  overflow: hidden;\r\n  min-height: 250px;\r\n  cursor: pointer;\r\n}\r\n\r\n@media (max-width: 580px) {\r\n  .n64-art {\r\n    border-right: none;\r\n    border-bottom: 1px solid var(--line);\r\n    min-height: 200px;\r\n  }\r\n}\r\n\r\n.n64-art-img {\r\n  position: relative;\r\n  z-index: 1;\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.3s ease;\r\n}\r\n\r\n.n64-card:hover .n64-art-img {\r\n  transform: scale(1.04);\r\n}\r\n\r\n.n64-body {\r\n  padding: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  gap: 14px;\r\n}\r\n\r\n.n64-badges {\r\n  display: flex;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n  margin-bottom: 10px;\r\n}\r\n\r\n.pill {\r\n  font: 700 9.5px var(--mono);\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.5px;\r\n  padding: 4px 8px;\r\n  border-radius: 5px;\r\n  background: rgba(14, 18, 28, 0.92);\r\n  color: #FFFFFF;\r\n  border: 1px solid var(--line-bright);\r\n}\r\n\r\n.pill.n64 {\r\n  background: linear-gradient(135deg, #00E5FF, #0077FF);\r\n  color: #FFFFFF;\r\n  border-color: transparent;\r\n  font-weight: 800;\r\n}\r\n\r\n.pill.ptbr {\r\n  background: rgba(16, 185, 129, 0.2);\r\n  color: #10B981;\r\n  border-color: rgba(16, 185, 129, 0.45);\r\n}\r\n\r\n.pill.gold {\r\n  background: rgba(255, 215, 0, 0.2);\r\n  color: #FFD700;\r\n  border-color: rgba(255, 215, 0, 0.5);\r\n}\r\n\r\n.n64-body h3 {\r\n  font-family: var(--display);\r\n  font-size: 21px;\r\n  letter-spacing: -0.5px;\r\n  margin: 0 0 8px;\r\n  line-height: 1.25;\r\n  color: #FFFFFF;\r\n}\r\n\r\n.n64-body p {\r\n  font-size: 13.5px;\r\n  color: var(--muted);\r\n  line-height: 1.55;\r\n  margin: 0;\r\n}\r\n\r\n.n64-actions {\r\n  display: flex;\r\n  gap: 10px;\r\n  align-items: center;\r\n  padding-top: 12px;\r\n  border-top: 1px solid var(--line);\r\n}\r\n\r\n.btn-launch-n64 {\r\n  flex: 1;\r\n  display: inline-flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  gap: 8px;\r\n  min-height: 44px;\r\n  padding: 11px 16px;\r\n  border-radius: var(--radius-sm);\r\n  border: 1px solid var(--n64-blue);\r\n  background: linear-gradient(135deg, #00C4DF, #0066EE);\r\n  color: #FFFFFF;\r\n  font: 700 12.5px var(--sans);\r\n  transition: all 0.16s ease;\r\n  box-shadow: 0 2px 10px rgba(0, 229, 255, 0.25);\r\n}\r\n\r\n.btn-launch-n64:hover {\r\n  background: linear-gradient(135deg, #33ECFF, #1A7BFF);\r\n  transform: translateY(-1px);\r\n  box-shadow: 0 4px 14px rgba(0, 229, 255, 0.4);\r\n}\r\n\r\n/* CONTROL DECK (SEÇÃO B) */\r\n.control-deck {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-lg);\r\n  padding: 16px;\r\n  margin-bottom: 20px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 14px;\r\n}\r\n\r\n.deck-top {\r\n  display: flex;\r\n  gap: 12px;\r\n  align-items: center;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.search-wrap {\r\n  flex: 1;\r\n  min-width: 240px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n  background: #080A10;\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-sm);\r\n  padding: 0 14px;\r\n  height: 46px;\r\n  transition: border-color 0.18s;\r\n}\r\n\r\n.search-wrap:focus-within {\r\n  border-color: var(--n64-blue);\r\n}\r\n\r\n.search-wrap input {\r\n  flex: 1;\r\n  background: transparent;\r\n  border: 0;\r\n  outline: 0;\r\n  color: #FFFFFF;\r\n  font-size: 14px;\r\n}\r\n\r\n.genre-tabs {\r\n  display: flex;\r\n  gap: 7px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.genre-tab {\r\n  border: 1px solid var(--line);\r\n  background: var(--panel-elevated);\r\n  color: var(--muted);\r\n  min-height: 38px;\r\n  padding: 8px 13px;\r\n  border-radius: var(--radius-sm);\r\n  font: 600 12px var(--sans);\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.genre-tab:hover {\r\n  color: #FFFFFF;\r\n  border-color: var(--line-bright);\r\n  background: var(--panel-hover);\r\n}\r\n\r\n.genre-tab.active {\r\n  background: #FFFFFF;\r\n  border-color: #FFFFFF;\r\n  color: #0c0f17;\r\n  font-weight: 700;\r\n}\r\n\r\n/* CATALOG CARDS GRID */\r\n.grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\r\n  gap: 20px;\r\n}\r\n\r\n.card {\r\n  border: 1px solid var(--line);\r\n  background: var(--panel);\r\n  border-radius: var(--radius-md);\r\n  overflow: hidden;\r\n  display: flex;\r\n  flex-direction: column;\r\n  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;\r\n  position: relative;\r\n}\r\n\r\n.card:hover {\r\n  transform: translateY(-3px);\r\n  border-color: var(--n64-blue);\r\n  box-shadow: 0 10px 24px rgba(0, 229, 255, 0.12);\r\n}\r\n\r\n.art {\r\n  aspect-ratio: 16 / 11;\r\n  position: relative;\r\n  overflow: hidden;\r\n  background: #080A10;\r\n  display: grid;\r\n  place-items: center;\r\n  border-bottom: 1px solid var(--line);\r\n  cursor: pointer;\r\n}\r\n\r\n.art-img {\r\n  position: relative;\r\n  z-index: 1;\r\n  width: 100%;\r\n  height: 100%;\r\n  object-fit: cover;\r\n  transition: transform 0.25s ease;\r\n}\r\n\r\n.card:hover .art-img {\r\n  transform: scale(1.04);\r\n}\r\n\r\n.art-fallback {\r\n  position: relative;\r\n  z-index: 1;\r\n  padding: 14px;\r\n  text-align: center;\r\n  font-weight: 700;\r\n  color: #9AA5B8;\r\n}\r\n\r\n.card-badges {\r\n  position: absolute;\r\n  top: 10px;\r\n  left: 10px;\r\n  z-index: 2;\r\n  display: flex;\r\n  gap: 6px;\r\n  flex-wrap: wrap;\r\n}\r\n\r\n.fav-btn {\r\n  position: absolute;\r\n  top: 10px;\r\n  right: 10px;\r\n  z-index: 2;\r\n  width: 34px;\r\n  height: 34px;\r\n  border-radius: 50%;\r\n  border: 1px solid rgba(255, 255, 255, 0.25);\r\n  background: rgba(12, 15, 23, 0.78);\r\n  backdrop-filter: blur(6px);\r\n  -webkit-backdrop-filter: blur(6px);\r\n  color: #FFFFFF;\r\n  display: grid;\r\n  place-items: center;\r\n  font-size: 16px;\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.fav-btn:hover {\r\n  background: #FFFFFF;\r\n  color: #0c0f17;\r\n  transform: scale(1.08);\r\n}\r\n\r\n.fav-btn.active {\r\n  background: var(--n64-yellow);\r\n  color: #0c0f17;\r\n  border-color: var(--n64-yellow);\r\n}\r\n\r\n.info {\r\n  padding: 16px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  justify-content: space-between;\r\n  flex: 1;\r\n  gap: 14px;\r\n}\r\n\r\n.title {\r\n  font-family: var(--display);\r\n  font-size: 16.5px;\r\n  font-weight: 700;\r\n  color: #FFFFFF;\r\n  line-height: 1.3;\r\n}\r\n\r\n.raw-sub {\r\n  font-size: 12.5px;\r\n  color: var(--muted);\r\n  margin-top: 4px;\r\n}\r\n\r\n.meta {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding-top: 10px;\r\n  border-top: 1px solid var(--line);\r\n  font-size: 12px;\r\n  color: var(--dim);\r\n}\r\n\r\n.play {\r\n  background: linear-gradient(135deg, #00C4DF, #0066EE);\r\n  color: #FFFFFF;\r\n  border: none;\r\n  font: 700 11.5px var(--sans);\r\n  padding: 7px 14px;\r\n  border-radius: 6px;\r\n  transition: all 0.16s ease;\r\n}\r\n\r\n.play:hover {\r\n  background: linear-gradient(135deg, #33ECFF, #1A7BFF);\r\n  transform: translateY(-1px);\r\n}\r\n\r\n/* SECTION C: GUIDE & CONTROLS */\r\n.guide-grid {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, 1fr);\r\n  gap: 20px;\r\n}\r\n\r\n@media (max-width: 860px) {\r\n  .guide-grid {\r\n    grid-template-columns: 1fr;\r\n  }\r\n}\r\n\r\n.guide-card {\r\n  background: var(--panel);\r\n  border: 1px solid var(--line-bright);\r\n  border-radius: var(--radius-md);\r\n  padding: 22px;\r\n}\r\n\r\n.guide-card h3 {\r\n  font-family: var(--display);\r\n  font-size: 18px;\r\n  color: #FFFFFF;\r\n  margin: 0 0 16px;\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 10px;\r\n}\r\n\r\n.keymap-grid {\r\n  display: grid;\r\n  gap: 10px;\r\n}\r\n\r\n.key-row {\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  padding: 8px 12px;\r\n  background: var(--bg-soft);\r\n  border-radius: 6px;\r\n  border: 1px solid var(--line);\r\n  font-size: 13px;\r\n}\r\n\r\n.key-row b {\r\n  font-family: var(--mono);\r\n  font-size: 12px;\r\n  color: #FFFFFF;\r\n  background: var(--panel-elevated);\r\n  padding: 3px 8px;\r\n  border-radius: 4px;\r\n  border: 1px solid var(--line-bright);\r\n}\r\n\r\n.key-row b.blue {\r\n  color: var(--n64-blue);\r\n  border-color: var(--n64-blue-border);\r\n}\r\n\r\n.key-row b.yellow {\r\n  color: var(--n64-yellow);\r\n  border-color: rgba(255, 215, 0, 0.4);\r\n}\r\n\r\n.key-row b.green {\r\n  color: var(--n64-green);\r\n  border-color: rgba(16, 185, 129, 0.4);\r\n}\r\n\r\n/* FOOTER */\r\n.footer {\r\n  margin: 48px 0 32px;\r\n  padding-top: 24px;\r\n  border-top: 1px solid var(--line);\r\n  display: flex;\r\n  justify-content: space-between;\r\n  align-items: center;\r\n  font: 600 12px var(--sans);\r\n  color: var(--dim);\r\n  flex-wrap: wrap;\r\n  gap: 12px;\r\n}\r\n\r\n.footer b {\r\n  color: #FFFFFF;\r\n}\r\n\r\n.empty {\r\n  text-align: center;\r\n  padding: 48px 20px;\r\n  background: var(--panel);\r\n  border-radius: var(--radius-md);\r\n  border: 1px dashed var(--line-bright);\r\n  color: var(--muted);\r\n  font-size: 14px;\r\n}\r\n\r\n@media (max-width: 860px) {\r\n  .shell { padding: 0 16px; }\r\n  .topbar {\r\n    flex-wrap: wrap;\r\n    padding: 10px 16px 6px;\r\n    height: auto;\r\n    min-height: unset;\r\n    gap: 0;\r\n  }\r\n  .brand {\r\n    order: 1;\r\n  }\r\n  .top-right-actions {\r\n    order: 2;\r\n    margin-left: auto;\r\n    gap: 8px;\r\n    padding-left: 0;\r\n    border-left: none;\r\n  }\r\n  .nav {\r\n    order: 3;\r\n    width: 100%;\r\n    flex: 0 0 100%;\r\n    margin-top: 8px;\r\n    padding: 8px 0 10px;\r\n    border-top: 1px solid var(--line);\r\n    overflow-x: auto;\r\n    overflow-y: hidden;\r\n    white-space: nowrap;\r\n    -webkit-overflow-scrolling: touch;\r\n  }\r\n  .hero {\r\n    padding: 24px 0 20px;\r\n    gap: 20px;\r\n  }\r\n}\r\n\r\n@media (max-width: 600px) {\r\n  .hero h1 {\r\n    font-size: 26px;\r\n  }\r\n  .grid {\r\n    grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));\r\n    gap: 12px;\r\n  }\r\n  .card-badges {\r\n    top: 6px;\r\n    left: 6px;\r\n  }\r\n  .fav-btn {\r\n    top: 6px;\r\n    right: 6px;\r\n    width: 30px;\r\n    height: 30px;\r\n    font-size: 14px;\r\n  }\r\n  .info {\r\n    padding: 12px;\r\n    gap: 8px;\r\n  }\r\n  .title {\r\n    font-size: 14px;\r\n  }\r\n  .player-dock {\r\n    margin-bottom: 24px;\r\n  }\r\n  .player-head {\r\n    padding: 10px 12px;\r\n    gap: 10px;\r\n  }\r\n  .player-now {\r\n    width: 100%;\r\n    gap: 10px;\r\n  }\r\n  .player-thumb {\r\n    width: 44px;\r\n    height: 44px;\r\n    flex-shrink: 0;\r\n  }\r\n  .player-title {\r\n    font-size: 15px;\r\n    line-height: 1.25;\r\n    word-break: break-word;\r\n  }\r\n  .player-controls-bar {\r\n    width: 100%;\r\n    flex-wrap: wrap;\r\n    gap: 6px;\r\n  }\r\n  .dock-btn {\r\n    padding: 7px 10px;\r\n    font-size: 11.5px;\r\n    flex: 1 1 auto;\r\n    min-width: calc(50% - 6px);\r\n    text-align: center;\r\n    justify-content: center;\r\n    min-height: 36px;\r\n  }\r\n  .cheat-sheet {\r\n    font-size: 11px;\r\n    padding: 10px 12px;\r\n    flex-direction: column;\r\n    gap: 6px;\r\n  }\r\n  #game-frame {\r\n    min-height: 220px;\r\n  }\r\n  .btn-top-mapper {\r\n    padding: 6px 10px;\r\n    font-size: 11px;\r\n  }\r\n  .brand-logo-img {\r\n    height: 34px;\r\n  }\r\n}\r\n</style>\r\n<script src=\"assets/gamepad-mapper.js\" defer></script>\r\n<script src=\"assets/retro-bg.js\" defer></script>\r\n</head>\r\n<body>\r\n\r\n<div class=\"topbar-wrap\">\r\n  <header class=\"topbar\">\r\n    <a class=\"brand\" href=\"index.html\" title=\"Continue? — Videogame Grátis\">\r\n      <img src=\"assets/continue-logo.png\" alt=\"Continue?\" class=\"brand-logo-img\">\r\n      <span class=\"brand-sub\">NINTENDO 64</span>\r\n    </a>\r\n    <nav class=\"nav\" aria-label=\"Navegação Principal\">\r\n      <a class=\"nav-link\" href=\"index.html\">🏠 Início</a>\r\n      <a class=\"nav-link\" href=\"snes.html\">🎮 Super Nintendo <span class=\"nav-badge\">550</span></a>\r\n      <a class=\"nav-link\" href=\"ps1.html\">💿 PlayStation 1 <span class=\"nav-badge\">16</span></a>\r\n      <a class=\"nav-link\" href=\"neogeo.html\">🕹️ Neo Geo <span class=\"nav-badge\">165</span></a>\r\n      <a class=\"nav-link active\" href=\"n64.html\">🌟 Nintendo 64 <span class=\"nav-badge blue\" id=\"nav-n64-count\">7</span></a>\r\n      <a class=\"nav-link\" href=\"gameboy.html\">📱 Game Boy <span class=\"nav-badge\">6</span></a>\r\n      <a class=\"nav-link\" href=\"sega.html\">⚡ Mega Drive <span class=\"nav-badge\">6</span></a>\r\n      <a class=\"nav-link\" href=\"psp.html\">🚀 PSP <span class=\"nav-badge\">2</span></a>\r\n      <a class=\"nav-link\" href=\"#catalogo\" id=\"nav-fav-trigger\">★ Favoritos <span class=\"nav-badge red\" id=\"fav-nav-count\">0</span></a>\r\n    </nav>\r\n    <div class=\"top-right-actions\">\r\n      <button type=\"button\" class=\"btn-top-mapper\" data-open-mapper title=\"Configurar Controle, Teclado ou Botões do Celular\">\r\n        <span class=\"pad-dot\"></span> 🕹️ Configurar Controle\r\n      </button>\r\n    </div>\r\n  </header>\r\n</div>\r\n\r\n<div class=\"shell\">\r\n  <main>\r\n    <!-- HERO -->\r\n    <section class=\"hero\">\r\n      <div>\r\n        <div class=\"eyebrow\">// 7 clássicos 3D em português (PT-BR) • celular, pc e controle</div>\r\n        <h1>Nintendo 64:<br><span>os mestres da revolução 3D!</span></h1>\r\n        <p class=\"intro\">\r\n          Os maiores épicos tridimensionais da história dos videogames traduzidos para o nosso idioma! <b>Super Mario 64</b>, <b>The Legend of Zelda: Ocarina of Time Redux & Master Quest</b>, <b>Majora's Mask Widescreen</b>, <b>Conker's Bad Fur Day Sem Censura</b>, <b>Mario Kart 64</b> e <b>Diddy Kong Racing</b>. <b>No celular, analógico virtual e botões C amarelos já aparecem na tela!</b>\r\n        </p>\r\n      </div>\r\n      <div class=\"hero-actions\">\r\n        <button class=\"btn-mapper-hero yellow\" id=\"btn-random-n64\" type=\"button\">🎲 Jogo Surpresa N64!</button>\r\n        <button class=\"btn-mapper-hero\" type=\"button\" data-open-mapper style=\"background:var(--panel-elevated);border-color:var(--line-bright)\">🕹️ Configurar Controle</button>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- BARRA DE BUSCA PRINCIPAL (NO TOPO) -->\r\n    <div class=\"top-search-banner\">\r\n      <label class=\"top-search-box\">\r\n        <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\">\r\n          <circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/>\r\n        </svg>\r\n        <input id=\"search-top\" type=\"search\" placeholder=\"🔍 Digite o nome do jogo de N64 (ex: Mario 64, Zelda, Conker, Mario Kart, Diddy Kong)...\" aria-label=\"Buscar jogo\">\r\n        <button class=\"top-clear-btn\" id=\"clear-search-top\" type=\"button\">LIMPAR ✕</button>\r\n      </label>\r\n      <div class=\"top-search-hints\">\r\n        <span>⚡ <b>Busca Rápida:</b></span>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Todos\">Todos</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Super Mario 64\">Super Mario 64</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Ocarina of Time\">Zelda Ocarina</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Majora's Mask\">Majora's Mask</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Conker\">Conker 18+</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Mario Kart 64\">Mario Kart 64</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Diddy Kong\">Diddy Kong Racing</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Aventura / RPG\">Aventura / RPG</button>\r\n        <button type=\"button\" class=\"search-tag\" data-search-term=\"Corrida\">Corrida</button>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- QUICK SECTION JUMP BAR -->\r\n    <nav class=\"section-nav\" aria-label=\"Atalhos da Biblioteca N64\">\r\n      <div class=\"jump-links\">\r\n        <a class=\"jump-pill\" href=\"#destaques\"><span>A</span> Destaques 3D N64 (7)</a>\r\n        <a class=\"jump-pill\" href=\"#catalogo\"><span>B</span> Catálogo & Filtros por Gênero</a>\r\n        <a class=\"jump-pill\" href=\"#guia-n64\"><span>C</span> Comandos do N64 & Dicas</a>\r\n      </div>\r\n      <span style=\"font:600 12px var(--sans);color:var(--muted)\">📱 Toque em qualquer jogo para carregar e jogar na hora!</span>\r\n    </nav>\r\n\r\n    <!-- THEATER MODE N64 PLAYER DOCK -->\r\n    <section class=\"player-dock\" id=\"player\" aria-label=\"Emulador Nintendo 64\">\r\n      <div class=\"player-head\">\r\n        <div class=\"player-now\">\r\n          <img class=\"player-thumb\" id=\"playing-thumb\" src=\"assets/covers/n64/super-mario-64.png\" alt=\"Capa do jogo\">\r\n          <div>\r\n            <div class=\"player-kicker\" id=\"playing-meta\">// JOGANDO AGORA • NINTENDO 64 • 3D 64-BIT</div>\r\n            <div class=\"player-title\" id=\"playing\">Carregando jogo…</div>\r\n          </div>\r\n        </div>\r\n        <div class=\"player-controls-bar\">\r\n          <button class=\"dock-btn\" type=\"button\" data-open-mapper>🕹️ Controle</button>\r\n          <button class=\"dock-btn\" id=\"dock-fav\" type=\"button\">★ Favoritar</button>\r\n          <button class=\"dock-btn\" id=\"dock-fullscreen\" type=\"button\">⛶ Tela Cheia</button>\r\n          <button class=\"dock-btn danger\" id=\"close\" type=\"button\">✕ Fechar Jogo</button>\r\n        </div>\r\n      </div>\r\n      <div class=\"control-note\">\r\n        <span>🕹️ <b>ANALÓGICO 3D:</b> Setas ou I/K/J/L · 🅰️ <b>A:</b> Z · 🅱️ <b>B:</b> X · ⚡ <b>Z:</b> A · 🟡 <b>BOTÕES C:</b> Delete, End, Home, PgDn · ▶ <b>START:</b> Enter</span>\r\n        <span>Quer mudar os botões? Toque em <b>🕹️ Controle</b> acima!</span>\r\n      </div>\r\n      <iframe id=\"game-frame\" title=\"Emulador Nintendo 64\" allow=\"autoplay; fullscreen; gamepad\" allowfullscreen></iframe>\r\n    </section>\r\n\r\n    <!-- SEÇÃO A: DESTAQUES N64 -->\r\n    <section class=\"lib-section\" id=\"destaques\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção A · obras-primas da geração 64-bit</div>\r\n          <h2>Destaques Nintendo 64 (PT-BR)</h2>\r\n          <p class=\"section-sub\">Aventuras consagradas com gráficos poligonais 3D, todas com tradução em português.</p>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"n64-showcase\" id=\"n64-showcase\"></div>\r\n    </section>\r\n\r\n    <!-- SEÇÃO B: CATÁLOGO COMPLETO & FILTROS -->\r\n    <section class=\"lib-section\" id=\"catalogo\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção B · acervo completo</div>\r\n          <h2>Catálogo de Jogos & Filtros</h2>\r\n          <p class=\"section-sub\">Filtre por estilo de jogo ou pesquise pelo título.</p>\r\n        </div>\r\n        <span id=\"count\" style=\"font:700 12.5px var(--mono);color:#FFFFFF\">Carregando jogos…</span>\r\n      </div>\r\n\r\n      <div class=\"control-deck\">\r\n        <div class=\"deck-top\">\r\n          <label class=\"search-wrap\">\r\n            <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\r\n              <circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/>\r\n            </svg>\r\n            <input id=\"search\" type=\"search\" placeholder=\"Buscar jogo de Nintendo 64 pelo nome…\" aria-label=\"Buscar jogo pelo nome\">\r\n          </label>\r\n          <div class=\"genre-tabs\" id=\"genre-tabs\"></div>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"grid\" id=\"grid\">\r\n        <div class=\"empty\">Carregando os clássicos de Nintendo 64…</div>\r\n      </div>\r\n    </section>\r\n\r\n    <!-- SEÇÃO C: GUIA DE COMANDOS DO N64 -->\r\n    <section class=\"lib-section\" id=\"guia-n64\">\r\n      <div class=\"section-header\">\r\n        <div>\r\n          <div class=\"section-index\">// seção C · comandos do controle trident & dicas</div>\r\n          <h2>Layout do Controle Nintendo 64</h2>\r\n          <p class=\"section-sub\">Entenda a distribuição do icônico joystick de 3 pontas do N64 no teclado ou gamepad:</p>\r\n        </div>\r\n        <button class=\"btn-mapper-hero\" type=\"button\" data-open-mapper style=\"min-height:42px;padding:10px 16px;font-size:12px\">🎯 Mapear Meu Controle</button>\r\n      </div>\r\n\r\n      <div class=\"guide-grid\">\r\n        <div class=\"guide-card\">\r\n          <h3>🕹️ Mapeamento Padrão de Teclado & Gamepad</h3>\r\n          <div class=\"keymap-grid\">\r\n            <div class=\"key-row\"><span>🕹️ Analógico 3D (Movimentação)</span><b class=\"blue\">Setas / I, K, J, L / Analógico Esquerdo</b></div>\r\n            <div class=\"key-row\"><span>🅰️ Botão A Azul (Pular / Acelerar)</span><b>Tecla Z / Botão Sul (A ou X)</b></div>\r\n            <div class=\"key-row\"><span>🅱️ Botão B Verde (Atacar / Falar / Freio)</span><b>Tecla X / Botão Leste (B ou Círculo)</b></div>\r\n            <div class=\"key-row\"><span>⚡ Gatilho Z Traseiro (Abaixar / Mira Z)</span><b class=\"yellow\">Tecla A / Gatilho L2 (LT)</b></div>\r\n            <div class=\"key-row\"><span>🟡 Botões C Amarelos (Câmera / Itens)</span><b class=\"yellow\">Home, End, Del, PgDn / Analógico Dir.</b></div>\r\n            <div class=\"key-row\"><span>🛡️ Gatilho R / L (Escudo / Ajustes)</span><b>Tecla W e Q / Gatilhos R1 e L1</b></div>\r\n            <div class=\"key-row\"><span>▶ Botão START Vermelho (Pausar)</span><b class=\"green\">Enter / Botão Start</b></div>\r\n            <div class=\"key-row\"><span>📱 No Celular</span><b class=\"blue\">Analógico Virtual & Botões na Tela</b></div>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"guide-card\">\r\n          <h3>💡 Dicas para a Melhor Experiência 3D</h3>\r\n          <p style=\"color:var(--muted);font-size:13.5px;line-height:1.6;margin:0 0 12px\">\r\n            O Nintendo 64 inaugurou câmeras tridimensionais livres e movimentação analógica analógica de 360 graus:\r\n          </p>\r\n          <ol style=\"color:var(--ink);font-size:13.5px;line-height:1.7;padding-left:18px;margin:0\">\r\n            <li><b>Trava Z (Z-Targeting):</b> Em Zelda Ocarina of Time e Majora's Mask, segure o <b>Gatilho Z</b> (tecla A no PC ou L2 no controle) para travar a câmera nos inimigos.</li>\r\n            <li><b>Girar o Celular:</b> No celular, vire o aparelho deitado (horizontal) e toque em <b>Tela Cheia</b> para que os botões fiquem confortáveis nas pontas dos dedos.</li>\r\n            <li><b>Controle Bluetooth:</b> Conecte qualquer joystick de Xbox, PlayStation ou 8BitDo via Bluetooth no celular ou PC — o emulador reconhece automaticamente!</li>\r\n          </ol>\r\n        </div>\r\n      </div>\r\n    </section>\r\n  </main>\r\n\r\n  <footer class=\"footer\">\r\n    <span>NINTENDO 64 NO NAVEGADOR • <b>CONTINUE?</b></span>\r\n    <span>SUPER NINTENDO • PLAYSTATION 1 • NEO GEO • NINTENDO 64 • 2026</span>\r\n  </footer>\r\n</div>\r\n\r\n<script>\r\n// Sintetizador de áudio retro suave (Web Audio API) para cliques nos botões\r\nconst RetroAudio = {\r\n  ctx: null,\r\n  init() {\r\n    if (!this.ctx && (window.AudioContext || window.webkitAudioContext)) {\r\n      this.ctx = new (window.AudioContext || window.webkitAudioContext)();\r\n    }\r\n  },\r\n  playClick() {\r\n    try {\r\n      this.init();\r\n      if (!this.ctx) return;\r\n      if (this.ctx.state === 'suspended') this.ctx.resume();\r\n      const osc = this.ctx.createOscillator();\r\n      const gain = this.ctx.createGain();\r\n      osc.type = 'triangle';\r\n      osc.frequency.setValueAtTime(520, this.ctx.currentTime);\r\n      osc.frequency.exponentialRampToValueAtTime(780, this.ctx.currentTime + 0.05);\r\n      gain.gain.setValueAtTime(0.04, this.ctx.currentTime);\r\n      gain.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 0.05);\r\n      osc.connect(gain);\r\n      gain.connect(this.ctx.destination);\r\n      osc.start();\r\n      osc.stop(this.ctx.currentTime + 0.05);\r\n    } catch (e) {}\r\n  }\r\n};\r\n\r\nconst FAV_KEY = 'continue_favorites_v1';\r\nconst grid = document.querySelector('#grid');\r\nconst n64Showcase = document.querySelector('#n64-showcase');\r\nconst search = document.querySelector('#search');\r\nconst searchTop = document.querySelector('#search-top');\r\nconst clearSearchTop = document.querySelector('#clear-search-top');\r\nconst count = document.querySelector('#count');\r\nconst player = document.querySelector('#player');\r\nconst frame = document.querySelector('#game-frame');\r\nconst genreTabs = document.querySelector('#genre-tabs');\r\n\r\nlet roms = [];\r\nlet selectedCategory = 'Todos';\r\nlet currentPlayingFile = null;\r\n\r\nfunction getFavorites() {\r\n  try { return JSON.parse(localStorage.getItem(FAV_KEY) || '[]'); } catch { return []; }\r\n}\r\n\r\nfunction toggleFavorite(name) {\r\n  RetroAudio.playClick();\r\n  const favs = getFavorites();\r\n  const idx = favs.indexOf(name);\r\n  if (idx >= 0) favs.splice(idx, 1);\r\n  else favs.unshift(name);\r\n  try { localStorage.setItem(FAV_KEY, JSON.stringify(favs)); } catch {}\r\n  updateFavCount();\r\n  renderShowcase();\r\n  renderGenreTabs();\r\n  render();\r\n  syncDockFavButton();\r\n}\r\n\r\nfunction updateFavCount() {\r\n  const el = document.querySelector('#fav-nav-count');\r\n  if (el) el.textContent = getFavorites().length;\r\n}\r\n\r\nfunction cleanName(fileOrName) {\r\n  if (typeof fileOrName === 'object' && fileOrName !== null) {\r\n    if (fileOrName.title) return fileOrName.title;\r\n    fileOrName = fileOrName.name || '';\r\n  }\r\n  return String(fileOrName)\r\n    .replace(/\\.(z64|n64|v64|rom|zip)$/i, '')\r\n    .trim();\r\n}\r\n\r\nfunction escapeHtml(s) {\r\n  return String(s || '').replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\r\n}\r\n\r\nfunction renderShowcase() {\r\n  if (!roms.length) {\r\n    n64Showcase.innerHTML = '';\r\n    return;\r\n  }\r\n  const favs = getFavorites();\r\n\r\n  n64Showcase.innerHTML = roms.map(f => {\r\n    const idx = roms.indexOf(f);\r\n    const title = cleanName(f);\r\n    const genre = f.genre || 'Nintendo 64';\r\n    const isFav = favs.includes(f.name);\r\n    const cover = f.cover || '';\r\n    const desc = f.description || 'Clássico 3D do Nintendo 64 totalmente em português!';\r\n\r\n    return `\r\n      <article class=\"n64-card\">\r\n        <div class=\"n64-art\" data-play-idx=\"${idx}\" title=\"Toque para jogar ${escapeHtml(title)}\">\r\n          ${cover ? `\r\n            <img class=\"n64-art-img\" src=\"${escapeHtml(cover)}\" alt=\"Capa de ${escapeHtml(title)}\" loading=\"lazy\" decoding=\"async\">\r\n          ` : `<span class=\"art-fallback\">${escapeHtml(title)}</span>`}\r\n        </div>\r\n        <div class=\"n64-body\">\r\n          <div>\r\n            <div class=\"n64-badges\">\r\n              <span class=\"pill n64\">🌟 N64</span>\r\n              <span class=\"pill ptbr\">PT-BR</span>\r\n              <span class=\"pill\">${escapeHtml(genre)}</span>\r\n              ${f.year ? `<span class=\"pill\">${escapeHtml(f.year)}</span>` : ''}\r\n            </div>\r\n            <h3>${escapeHtml(title)}</h3>\r\n            <p>${escapeHtml(desc)}</p>\r\n          </div>\r\n          <div class=\"n64-actions\">\r\n            <button class=\"btn-launch-n64\" type=\"button\" data-play-idx=\"${idx}\">JOGAR AGORA ▶</button>\r\n            <button class=\"dock-btn ${isFav ? 'active' : ''}\" type=\"button\" data-fav-name=\"${escapeHtml(f.name)}\" title=\"Favoritar\">★</button>\r\n          </div>\r\n        </div>\r\n      </article>\r\n    `;\r\n  }).join('');\r\n}\r\n\r\nfunction renderGenreTabs() {\r\n  const favSet = new Set(getFavorites());\r\n  const tabs = [\r\n    { id: 'Todos', label: `Todos (${roms.length})` },\r\n    { id: 'FEATURED', label: `★ Destaques (${roms.filter(r => r.featured).length})` },\r\n    { id: 'FAV', label: `♥ Favoritos (${roms.filter(r => favSet.has(r.name)).length})` }\r\n  ];\r\n\r\n  const genres = [...new Set(roms.map(r => r.genre || 'Nintendo 64'))].sort();\r\n  genres.forEach(g => {\r\n    tabs.push({ id: g, label: `${g} (${roms.filter(r => (r.genre || 'Nintendo 64') === g).length})` });\r\n  });\r\n\r\n  genreTabs.innerHTML = tabs.map(t => `\r\n    <button class=\"genre-tab ${selectedCategory === t.id ? 'active' : ''}\" type=\"button\" data-cat=\"${escapeHtml(t.id)}\">\r\n      ${escapeHtml(t.label)}\r\n    </button>\r\n  `).join('');\r\n}\r\n\r\nfunction render() {\r\n  const q = search.value.trim().toLocaleLowerCase('pt-BR');\r\n  const favSet = new Set(getFavorites());\r\n\r\n  const shown = roms.filter(f => {\r\n    if (selectedCategory === 'FAV' && !favSet.has(f.name)) return false;\r\n    if (selectedCategory === 'FEATURED' && !f.featured) return false;\r\n    if (!['Todos', 'FAV', 'FEATURED'].includes(selectedCategory) && (f.genre || 'Nintendo 64') !== selectedCategory) return false;\r\n\r\n    if (q) {\r\n      const matchName = (f.name || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      const matchTitle = (f.title || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      const matchGenre = (f.genre || '').toLocaleLowerCase('pt-BR').includes(q);\r\n      if (!matchName && !matchTitle && !matchGenre) return false;\r\n    }\r\n    return true;\r\n  });\r\n\r\n  count.textContent = `${shown.length} de ${roms.length} jogos disponíveis`;\r\n\r\n  grid.innerHTML = shown.length ? shown.map(f => {\r\n    const idx = roms.indexOf(f);\r\n    const title = cleanName(f);\r\n    const isFav = favSet.has(f.name);\r\n    const genre = f.genre || 'Nintendo 64';\r\n    const cover = f.cover || '';\r\n\r\n    return `\r\n      <article class=\"card\">\r\n        <div class=\"art\" data-play-idx=\"${idx}\" title=\"Toque para jogar ${escapeHtml(title)}\">\r\n          ${cover ? `\r\n            <img class=\"art-img\" src=\"${escapeHtml(cover)}\" alt=\"Capa de ${escapeHtml(title)}\" loading=\"lazy\" decoding=\"async\">\r\n          ` : `<span class=\"art-fallback\">${escapeHtml(title)}</span>`}\r\n          <div class=\"card-badges\">\r\n            <span class=\"pill n64\">N64</span>\r\n            <span class=\"pill ptbr\">PT-BR</span>\r\n          </div>\r\n          <button class=\"fav-btn ${isFav ? 'active' : ''}\" type=\"button\" data-fav-name=\"${escapeHtml(f.name)}\" title=\"Guardar nos Favoritos\">★</button>\r\n        </div>\r\n        <div class=\"info\">\r\n          <div>\r\n            <div class=\"title\">${escapeHtml(title)}</div>\r\n            <div class=\"raw-sub\">${escapeHtml(genre)} ${f.year ? `• ${escapeHtml(f.year)}` : ''}</div>\r\n          </div>\r\n          <div class=\"meta\">\r\n            <span>64-Bit 3D</span>\r\n            <button class=\"play\" type=\"button\" data-play-idx=\"${idx}\">JOGAR ▶</button>\r\n          </div>\r\n        </div>\r\n      </article>\r\n    `;\r\n  }).join('') : '<div class=\"empty\">Nenhum jogo encontrado nessa busca ou filtro.</div>';\r\n}\r\n\r\nfunction syncDockFavButton() {\r\n  const btn = document.querySelector('#dock-fav');\r\n  if (!btn || !currentPlayingFile) return;\r\n  const isFav = getFavorites().includes(currentPlayingFile.name);\r\n  btn.classList.toggle('active', isFav);\r\n  btn.textContent = isFav ? '★ Favoritado' : '☆ Favoritar';\r\n}\r\n\r\nfunction start(file) {\r\n  if (!file) return;\r\n  RetroAudio.playClick();\r\n  currentPlayingFile = file;\r\n  const title = cleanName(file);\r\n  document.querySelector('#playing').textContent = title;\r\n  document.querySelector('#playing-meta').textContent = `// JOGANDO AGORA • NINTENDO 64 • ${file.genre || '3D'}`;\r\n  const thumb = document.querySelector('#playing-thumb');\r\n  if (file.cover) thumb.src = file.cover;\r\n\r\n  syncDockFavButton();\r\n  frame.src = 'n64-player.html?rom=' + encodeURIComponent(file.url) + '&title=' + encodeURIComponent(title);\r\n  player.classList.add('open');\r\n  player.scrollIntoView({ behavior: 'smooth', block: 'start' });\r\n}\r\n\r\n// Event Delegation para cliques nos jogos e botões\r\ndocument.addEventListener('click', (e) => {\r\n  const playTarget = e.target.closest('[data-play-idx]');\r\n  if (playTarget) {\r\n    const idx = parseInt(playTarget.dataset.playIdx, 10);\r\n    if (!isNaN(idx) && roms[idx]) {\r\n      start(roms[idx]);\r\n    }\r\n    return;\r\n  }\r\n\r\n  const favTarget = e.target.closest('[data-fav-name]');\r\n  if (favTarget) {\r\n    e.stopPropagation();\r\n    toggleFavorite(favTarget.dataset.favName);\r\n    return;\r\n  }\r\n\r\n  const catTarget = e.target.closest('.genre-tab');\r\n  if (catTarget) {\r\n    RetroAudio.playClick();\r\n    selectedCategory = catTarget.dataset.cat;\r\n    renderGenreTabs();\r\n    render();\r\n    return;\r\n  }\r\n\r\n  const searchTag = e.target.closest('.search-tag');\r\n  if (searchTag) {\r\n    RetroAudio.playClick();\r\n    const term = searchTag.dataset.searchTerm;\r\n    if (term === 'Todos') {\r\n      search.value = '';\r\n      searchTop.value = '';\r\n      selectedCategory = 'Todos';\r\n    } else if (['Aventura / RPG', 'Corrida', 'Plataforma 3D'].includes(term)) {\r\n      search.value = '';\r\n      searchTop.value = '';\r\n      selectedCategory = term;\r\n    } else {\r\n      search.value = term;\r\n      searchTop.value = term;\r\n      selectedCategory = 'Todos';\r\n    }\r\n    clearSearchTop.classList.toggle('visible', searchTop.value.length > 0);\r\n    renderGenreTabs();\r\n    render();\r\n    return;\r\n  }\r\n});\r\n\r\n// Barra de busca superior e catálogo sincronizadas\r\nsearch.addEventListener('input', () => {\r\n  searchTop.value = search.value;\r\n  clearSearchTop.classList.toggle('visible', search.value.length > 0);\r\n  render();\r\n});\r\n\r\nsearchTop.addEventListener('input', () => {\r\n  search.value = searchTop.value;\r\n  clearSearchTop.classList.toggle('visible', search.value.length > 0);\r\n  render();\r\n});\r\n\r\nclearSearchTop.addEventListener('click', () => {\r\n  RetroAudio.playClick();\r\n  search.value = '';\r\n  searchTop.value = '';\r\n  clearSearchTop.classList.remove('visible');\r\n  render();\r\n});\r\n\r\n// Botão Jogo Surpresa N64\r\ndocument.querySelector('#btn-random-n64').addEventListener('click', () => {\r\n  if (!roms.length) return;\r\n  const pick = roms[Math.floor(Math.random() * roms.length)];\r\n  start(pick);\r\n});\r\n\r\n// Controles do Player Dock\r\ndocument.querySelector('#close').addEventListener('click', () => {\r\n  RetroAudio.playClick();\r\n  frame.src = 'about:blank';\r\n  player.classList.remove('open');\r\n  currentPlayingFile = null;\r\n});\r\n\r\ndocument.querySelector('#dock-fullscreen').addEventListener('click', () => {\r\n  RetroAudio.playClick();\r\n  if (!frame) return;\r\n  if (frame.requestFullscreen) frame.requestFullscreen();\r\n  else if (frame.webkitRequestFullscreen) frame.webkitRequestFullscreen();\r\n});\r\n\r\ndocument.querySelector('#dock-fav').addEventListener('click', () => {\r\n  if (currentPlayingFile) toggleFavorite(currentPlayingFile.name);\r\n});\r\n\r\nasync function fetchN64CatalogWithFallback() {\r\n  try {\r\n    const res = await fetch('/api/n64', { cache: 'no-store' });\r\n    if (res.ok) {\r\n      const data = await res.json();\r\n      if (Array.isArray(data) && data.length) return data;\r\n    }\r\n  } catch {}\r\n  const fallback = await fetch('n64-games.json', { cache: 'no-store' });\r\n  if (!fallback.ok) throw new Error('Não consegui carregar o catálogo de Nintendo 64.');\r\n  return await fallback.json();\r\n}\r\n\r\nasync function loadLibrary() {\r\n  updateFavCount();\r\n  try {\r\n    const payload = await fetchN64CatalogWithFallback();\r\n    roms = (Array.isArray(payload) ? payload : []).filter(item => item && typeof item.name === 'string' && typeof item.url === 'string');\r\n    document.querySelector('#nav-n64-count').textContent = roms.length;\r\n\r\n    renderShowcase();\r\n    renderGenreTabs();\r\n    render();\r\n\r\n    const params = new URLSearchParams(location.search);\r\n    const playParam = params.get('play');\r\n    if (playParam) {\r\n      const target = roms.find(r => r.name === playParam || cleanName(r).toLocaleLowerCase('pt-BR') === playParam.toLocaleLowerCase('pt-BR'));\r\n      if (target) start(target);\r\n    }\r\n  } catch (error) {\r\n    count.textContent = 'Erro ao carregar catálogo';\r\n    grid.innerHTML = `<div class=\\\"empty\\\">${escapeHtml(error.message)}</div>`;\r\n  }\r\n}\r\n\r\nloadLibrary();\r\n</script>\r\n</body>\r\n</html>\r\n";
